  }
  if (statusCode === 429 || statusCode >= 500 || !statusCode) {
    return { state: 'ERROR', error_class: 'API_TRANSIENT', retryable: true, message: `Plagiarism API unavailable or rate limited (HTTP ${statusCode || 'no response'})` };
  }
